{
  "name": "是德科技示波器",
  "name_en": "Keysight Oscilloscope",
  "manufacturer": "Keysight Technologies",
  "description": "台式电子示波器，用于采集、显示和分析电信号随时间变化的波形。常用于实验室中观察电压波形、测量频率、周期、上升沿、下降沿、占空比、脉宽、过冲及峰峰值等参数，并可导出波形数据和屏幕截图；部分机型还支持数字电压表功能。",
  "description_en": "A benchtop electronic oscilloscope used to acquire, display, and analyze electrical waveforms over time. It is commonly used in laboratories to observe voltage signals and measure frequency, period, rise time, fall time, duty cycle, pulse width, overshoot, and peak-to-peak voltage, and can export waveform data and screen images; some models also support digital voltmeter functions.",
  "tag_hints": [
    "oscilloscope",
    "waveform acquisition",
    "electrical signal measurement",
    "SCPI instrument",
    "time-domain analysis",
    "screen capture",
    "waveform export",
    "digital voltmeter"
  ],
  "actions": [
    {
      "action_name": "auto-modeRun",
      "description": "将示波器设置为连续运行采集模式。",
      "description_en": "Set the oscilloscope to continuous run acquisition mode."
    },
    {
      "action_name": "auto-modeStop",
      "description": "停止示波器采集并保持当前显示。",
      "description_en": "Stop acquisition and hold the current display."
    },
    {
      "action_name": "auto-modeSingle",
      "description": "将示波器设置为单次采集模式。",
      "description_en": "Set the oscilloscope to single acquisition mode."
    },
    {
      "action_name": "auto-annotate",
      "description": "在屏幕上添加文字注释，可设置颜色和背景。",
      "description_en": "Add a text annotation to the screen, with optional color and background."
    },
    {
      "action_name": "auto-annotateColor",
      "description": "设置屏幕注释的颜色。",
      "description_en": "Set the color of the screen annotation."
    },
    {
      "action_name": "auto-annotateOff",
      "description": "关闭屏幕注释显示。",
      "description_en": "Turn off the screen annotation display."
    },
    {
      "action_name": "auto-channelLabel",
      "description": "为选定通道添加标签。",
      "description_en": "Add a label to the selected channel."
    },
    {
      "action_name": "auto-channelLabelOff",
      "description": "关闭通道标签显示。",
      "description_en": "Turn off channel label display."
    },
    {
      "action_name": "auto-setupAutoscale",
      "description": "对指定通道执行自动量程与自动显示优化。",
      "description_en": "Autoscale the specified channel or channels for optimal display."
    },
    {
      "action_name": "auto-hardcopy",
      "description": "保存当前示波器屏幕图像到文件。",
      "description_en": "Save the current oscilloscope screen image to a file."
    },
    {
      "action_name": "auto-waveformData",
      "description": "下载选定通道的波形数据。",
      "description_en": "Download waveform data from the selected channel."
    },
    {
      "action_name": "auto-DVMisEnabled",
      "description": "获取数字电压表模式是否已启用。",
      "description_en": "Get whether digital voltmeter mode is enabled."
    },
    {
      "action_name": "auto-enableDVM",
      "description": "启用或禁用数字电压表模式。",
      "description_en": "Enable or disable digital voltmeter mode."
    },
    {
      "action_name": "auto-measureDVMacrms",
      "description": "测量通道的交流有效值（去除直流分量）。",
      "description_en": "Measure the AC RMS value of the channel, with the DC component removed."
    },
    {
      "action_name": "auto-measureDVMdc",
      "description": "测量通道的直流电压值。",
      "description_en": "Measure the DC voltage value of the channel."
    },
    {
      "action_name": "auto-measureDVMdcrms",
      "description": "测量通道的直流有效值。",
      "description_en": "Measure the DC RMS value of the channel."
    },
    {
      "action_name": "auto-measureDVMfreq",
      "description": "测量通道的频率计读数。",
      "description_en": "Measure the frequency counter reading of the channel."
    },
    {
      "action_name": "auto-measureBitRate",
      "description": "测量信号的比特率。",
      "description_en": "Measure the bit rate of the signal."
    },
    {
      "action_name": "auto-measureBurstWidth",
      "description": "测量波形突发包络的宽度。",
      "description_en": "Measure the burst width of the waveform."
    },
    {
      "action_name": "auto-measureCounterFrequency",
      "description": "测量计数器频率。",
      "description_en": "Measure the counter frequency."
    },
    {
      "action_name": "auto-measurePosDutyCycle",
      "description": "测量正占空比。",
      "description_en": "Measure the positive duty cycle."
    },
    {
      "action_name": "auto-measureFallTime",
      "description": "测量下降时间。",
      "description_en": "Measure the fall time."
    },
    {
      "action_name": "auto-measureRiseTime",
      "description": "测量上升时间。",
      "description_en": "Measure the rise time."
    },
    {
      "action_name": "auto-measureFrequency",
      "description": "测量信号频率。",
      "description_en": "Measure the signal frequency."
    },
    {
      "action_name": "auto-measureNegDutyCycle",
      "description": "测量负占空比。",
      "description_en": "Measure the negative duty cycle."
    },
    {
      "action_name": "auto-measureFallEdgeCount",
      "description": "测量屏幕内的下降沿计数。",
      "description_en": "Measure the on-screen falling edge count."
    },
    {
      "action_name": "auto-measureFallPulseCount",
      "description": "测量屏幕内的负脉冲计数。",
      "description_en": "Measure the on-screen falling pulse count."
    },
    {
      "action_name": "auto-measureNegPulseWidth",
      "description": "测量负脉冲宽度。",
      "description_en": "Measure the negative pulse width."
    },
    {
      "action_name": "auto-measureOvershoot",
      "description": "测量波形过冲百分比。",
      "description_en": "Measure the waveform overshoot percentage."
    },
    {
      "action_name": "auto-measurePreshoot",
      "description": "测量波形前冲百分比。",
      "description_en": "Measure the waveform preshoot percentage."
    },
    {
      "action_name": "auto-measureRiseEdgeCount",
      "description": "测量屏幕内的上升沿计数。",
      "description_en": "Measure the on-screen rising edge count."
    },
    {
      "action_name": "auto-measureRisePulseCount",
      "description": "测量屏幕内的正脉冲计数。",
      "description_en": "Measure the on-screen rising pulse count."
    },
    {
      "action_name": "auto-measurePosPulseWidth",
      "description": "测量正脉冲宽度。",
      "description_en": "Measure the positive pulse width."
    },
    {
      "action_name": "auto-measurePeriod",
      "description": "测量信号周期。",
      "description_en": "Measure the signal period."
    },
    {
      "action_name": "auto-measureVoltAmplitude",
      "description": "测量波形电压幅度。",
      "description_en": "Measure the voltage amplitude of the waveform."
    },
    {
      "action_name": "auto-measureVoltAverage",
      "description": "测量平均电压。",
      "description_en": "Measure the average voltage."
    },
    {
      "action_name": "auto-measureVoltRMS",
      "description": "测量电压有效值。",
      "description_en": "Measure the RMS voltage."
    },
    {
      "action_name": "auto-measureVoltBase",
      "description": "测量波形基线电压。",
      "description_en": "Measure the waveform base voltage."
    },
    {
      "action_name": "auto-measureVoltTop",
      "description": "测量波形顶部电压。",
      "description_en": "Measure the waveform top voltage."
    },
    {
      "action_name": "auto-measureVoltMax",
      "description": "测量最大电压。",
      "description_en": "Measure the maximum voltage."
    },
    {
      "action_name": "auto-measureVoltMin",
      "description": "测量最小电压。",
      "description_en": "Measure the minimum voltage."
    },
    {
      "action_name": "auto-measureVoltPP",
      "description": "测量峰峰值电压。",
      "description_en": "Measure the peak-to-peak voltage."
    },
    {
      "action_name": "auto-measureTblUnits",
      "description": "获取指定测量项目的单位。",
      "description_en": "Get the units for a specified measurement item."
    },
    {
      "action_name": "auto-measureTblCall",
      "description": "执行指定测量项目并返回结果。",
      "description_en": "Run a specified measurement item and return the result."
    }
  ]
}

